<?php
function check($v,$m){if(!$v)throw new RuntimeException($m);}
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function cds_can_feature($p,$level){return $GLOBALS['allow']===null||in_array($p,$GLOBALS['allow'],true);}function cds_user(){return ['role'=>'admin'];}function cds_user_has_group($u,$g){return false;}
