check(array_column($home['groups'][4]['items'],'label')===['Nhập liệu','Phân công','Kết quả phiên bản'],'Exactly three assignment workflow entries');
foreach([['cm.nhaplieu','Nhập liệu','monhoc.php'],['cm.pccm','Phân công','them.php'],['cm.thongke','Kết quả phiên bản','thongke.php'],['cm.tracuu','Kết quả phiên bản','ketqua.php']]as[$permission,$label,$href]){$r=render_menu('index','',[$permission]);$groups=array_values(array_filter($r['groups'],fn($g)=>$g['label']==='Phân công chuyên môn'));check(count($groups)===1&&count($groups[0]['items'])===1&&$groups[0]['items'][0]['label']===$label&&$groups[0]['items'][0]['href']===$href,'Workflow menu retains original permission: '.$permission);}
$targets=[];foreach($home['groups']as$g)foreach($g['items']as$item){check(!isset($targets[$item['href']]),'No duplicate destination');$targets[$item['href']]=true;check(is_file(__DIR__.'/../chuyenmon/'.parse_url($item['href'],PHP_URL_PATH)),'Existing endpoint: '.$item['href']);}
foreach([['baocao','tiendo','Giảng dạy'],['baocao','dinhky','Báo cáo'],['baocao','thang','Báo cáo'],['kehoach','','Báo cáo'],['kehoach','chitieu','Báo cáo'],['activities','','Học tập'],['activities','online','Học tập'],['dugio','','Đánh giá'],['giaovien','','Phân công chuyên môn']]as[$page,$tab,$expected]){$r=render_menu($page,$tab);$open=array_values(array_filter($r['groups'],fn($g)=>$g['open']));check(count($open)===1&&$open[0]['label']===$expected,'Only current group opens: '.$page.'/'.$tab);}
